AI_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AgentWhite Local AI Analyst</title>
<style>
:root{--bg:#06100c;--panel:#0d1b15;--line:#204232;--text:#ddf9e9;--muted:#8eac9b;--green:#63ffa8;--red:#ff7777}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top,#11271d,var(--bg) 46%);color:var(--text);font:14px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}.shell{max-width:1000px;margin:auto;padding:24px}a,button,select{font:inherit}a,button{border:1px solid #32674d;background:#102a20;color:var(--text);padding:9px 12px;border-radius:9px;text-decoration:none;cursor:pointer}button.primary{color:var(--green);border-color:#3c8a61}.panel{background:rgba(13,27,21,.94);border:1px solid var(--line);border-radius:14px;padding:16px;margin-top:16px}.row{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.row select{background:#06100c;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:9px;min-width:220px}.muted{color:var(--muted)}pre{white-space:pre-wrap;word-break:break-word;background:#020704;border:1px solid var(--line);border-radius:10px;padding:14px;min-height:160px;max-height:62vh;overflow:auto}.priority{padding:10px;border-left:3px solid var(--green);background:#08130e;margin:8px 0}.error{color:var(--red)}h1{letter-spacing:.06em}h1 span{color:var(--green)}
</style></head>
<body><div class="shell">
<div class="row"><a href="/">← Command Center</a></div>
<h1>AGENT<span>WHITE</span> LOCAL AI ANALYST</h1>
<p class="muted">Analyzes only evidence AgentWhite has already recorded. If Ollama is not installed, the deterministic offline analyst still produces priorities and remediation.</p>
<div class="panel">
  <div class="row">
    <label>Target <select id="device"><option value="">All recorded findings</option></select></label>
    <label>Model <select id="model"><option value="">Automatic / offline fallback</option></select></label>
    <button class="primary" onclick="analyze()">Analyze Evidence</button>
  </div>
</div>
<div class="panel"><strong id="engine">Analyst ready.</strong><div id="summary" class="muted" style="margin-top:8px"></div><div id="priorities" style="margin-top:12px"></div></div>
<div class="panel"><strong>AI / Rule Analysis</strong><pre id="analysis">Choose a target or analyze all recorded evidence.</pre></div>
</div>
<script>
const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function api(path,opt={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d}
async function boot(){const s=await api('/api/state');for(const d of s.devices||[]){$('device').innerHTML+=`<option value="${esc(d.id)}">${esc(d.name)} · ${esc(d.kind)}</option>`}for(const m of (s.ai&&s.ai.models)||[]){$('model').innerHTML+=`<option>${esc(m)}</option>`}}
async function analyze(){$('analysis').textContent='Analyzing local evidence…';$('priorities').innerHTML='';try{const d=await api('/api/ai-analysis',{method:'POST',body:JSON.stringify({device_id:$('device').value,model:$('model').value})});$('engine').textContent=(d.engine||'AgentWhite analyst')+(d.model?' · '+d.model:'');$('summary').textContent=d.summary||'';$('priorities').innerHTML=(d.priorities||[]).map(p=>`<div class="priority"><b>${esc(p.severity)} · ${esc(p.finding)}</b><br>${esc(p.fix)}</div>`).join('');$('analysis').textContent=d.analysis||'Local Ollama is not available; remediation above was generated by the offline rule analyst.';if(d.ai_error)$('analysis').textContent+='\n\nLocal AI error: '+d.ai_error}catch(e){$('analysis').innerHTML='<span class="error">'+esc(e.message)+'</span>'}}
boot().catch(e=>$('analysis').textContent=e.message)
</script></body></html>'''
